import{_ as e,o as d,c as o,a4 as a}from"./chunks/framework.DpieW3qv.js";const h=JSON.parse('{"title":"Command Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md","lastUpdated":null}'),r={name:"reference/commands.md"};function c(s,t,i,l,n,u){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h1><p>Quick reference for all Makefile commands. For full syntax, flags, and example output, use the per-command pages under <a href="/ocapi-docs.github.io/cli/">Commands</a>.</p><h2 id="command-summary" tabindex="-1">Command summary <a class="header-anchor" href="#command-summary" aria-label="Permalink to &quot;Command summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Command</th><th>What it does</th><th>Typical output</th></tr></thead><tbody><tr><td>Setup</td><td><code>make setup</code></td><td>Configure brand, data source, OCAPI</td><td>Wizard; writes <code>dev-env/.ocapi-config.json</code></td></tr><tr><td>Setup</td><td><code>make health</code></td><td>Test SFCC connection</td><td><code>✔ OCAPI ready (NNNms)</code> or missing-env errors</td></tr><tr><td>1</td><td><code>make pull</code></td><td>Git sync + fetch + auto-build, then open status hub</td><td>Progress spinners; auto-builds only missing dates; opens status</td></tr><tr><td>2</td><td><code>make preview</code></td><td>Build if stale (diff + approval) + compose + preview file browser</td><td>Shows changes for approval if data changed; file browser for preview/ folder</td></tr><tr><td>3</td><td><code>make push</code></td><td>Validate + sync to SFCC + auto-email + replicate steps</td><td><code>✔ Synced …</code> + email + replication steps + staging URL</td></tr><tr><td>4</td><td><code>make commit</code></td><td>Save to Git (refresh dir only)</td><td><code>✔ Committed: brand date done</code></td></tr><tr><td>Status</td><td><code>make status</code></td><td>Interactive hub — pick refresh → pick action → run → back to board</td><td>Summary + picker (TTY) or full table</td></tr><tr><td>Also</td><td><code>make build</code></td><td>Build only (preview without zone picker)</td><td><code>✔ N files generated</code> or approval prompt</td></tr><tr><td>Also</td><td><code>make browse</code></td><td>Browse data files (assets, refresh.json, payload)</td><td>Tree view + file picker</td></tr><tr><td>Also</td><td><code>make replicate</code></td><td>Print replication steps (STG → POD)</td><td>Plain-text steps + staging URL</td></tr><tr><td>Also</td><td><code>make email</code></td><td>Generate changeout email (also runs automatically after <code>make push</code>)</td><td>Email body</td></tr><tr><td>Dev</td><td><code>make delete DATE=</code></td><td>Remove refresh from SFCC + local</td><td><code>✔ SFCC deleted</code> / <code>✔ Deleted local</code></td></tr><tr><td>Dev</td><td><code>make upload</code></td><td>Partial asset sync (push HTML changes only)</td><td>Sync summary</td></tr><tr><td>Dev</td><td><code>make registry</code></td><td>Show live asset registry</td><td>Zone list + item counts</td></tr><tr><td>Dev</td><td><code>make registry ARGS=&quot;--ipids&quot;</code></td><td>List all IPIDs in the registry</td><td>Asset type, zone, order, IPID</td></tr><tr><td>Dev</td><td><code>make test</code></td><td>Run all tests (Vitest)</td><td><code>Tests N passed</code></td></tr><tr><td>Dev</td><td><code>make test-watch</code></td><td>Run tests in watch mode</td><td>Re-runs on file change</td></tr><tr><td>Dev</td><td><code>make test-coverage</code></td><td>Run tests with coverage report (threshold: 64% statements)</td><td>Coverage summary + lcov</td></tr><tr><td>Dev</td><td><code>make test-brands</code></td><td>E2E test both brands (clean dev-env → excel → build → preview)</td><td>Per-brand output</td></tr><tr><td>Dev</td><td><code>make fresh-install</code></td><td>Full reset: remove dev-env + node_modules, npm ci, then make test-brands</td><td>Reinstall + E2E</td></tr><tr><td>Dev</td><td><code>make convert-excel INPUT=</code> [OUTPUT=]</td><td>Raw Excel → CONVERTED format (INPUT required)</td><td>Writes converted file</td></tr><tr><td>Dev</td><td><code>make check</code></td><td>Lint + tests + audit (CI gate)</td><td>Lint + test + audit output</td></tr><tr><td>Dev</td><td><code>make clean</code></td><td>Remove rendered previews</td><td><code>✔ Cleaned</code></td></tr><tr><td>Dev</td><td><code>make docs</code></td><td>Start docs dev server</td><td>VitePress URL</td></tr><tr><td>Dev</td><td><code>make reports [OP=dates]</code></td><td>Report: dates, stats, status, pending, history</td><td>See <a href="/ocapi-docs.github.io/cli/reports.html">reports</a></td></tr><tr><td>Dev</td><td><code>make validate [DATE=]</code></td><td>Data quality check only (no build/push)</td><td>See <a href="/ocapi-docs.github.io/cli/validate.html">validate</a></td></tr><tr><td>CI</td><td><code>make test-sync DATE=</code></td><td>Push to OCAPI with <code>--yes --force</code> (CI / non-interactive)</td><td>Sync output</td></tr><tr><td>CI</td><td><code>make build-all [FORCE=1]</code></td><td>Build <strong>every</strong> date for current brand</td><td>Per-date build output</td></tr><tr><td>CI</td><td><code>make push-all [YES=1] [FORCE=1]</code></td><td>Sync <strong>every</strong> date to SFCC (run after build-all)</td><td>Per-date sync output</td></tr><tr><td>Diag</td><td><code>make config</code></td><td>Print current configuration (no secrets; env var presence only)</td><td>Config summary</td></tr><tr><td>Diag</td><td><code>make doctor</code></td><td>Validate setup, config, brand, source, refresh dirs, OCAPI env</td><td>Pass/fail checklist</td></tr></tbody></table><p><strong>Test commands:</strong> Run <code>make test</code> for the full suite. Use <code>make test-watch</code> for watch mode, <code>make test-coverage</code> for coverage, and <code>make test-brands</code> for E2E both brands. Use <code>make fresh-install</code> for a full reset (deps + dev-env) then E2E. To run a subset by path: <code>npx vitest run tests/domain</code> or <code>npx vitest run tests/cli</code>.</p><p><strong>Approval guards:</strong> When data has already been built or synced and you run <code>make build</code> or <code>make push</code> again, the tool shows what changed (copy, destinations, items added/removed) and asks for approval instead of blocking. Use <code>FORCE=1</code> to skip the prompt (e.g., in CI). Use <code>YES=1</code> to auto-approve.</p><p><strong>build-all / push-all:</strong> For CI or batch runs. Run <code>make pull</code> first; then <code>make build-all</code> builds all dates; then <code>make push-all</code> syncs all of them to SFCC. Use <code>YES=1</code> to skip confirmation prompts. Use <code>FAIL_FAST=1</code> to stop on first failure (default: continue on error).</p><p><strong>Automation:</strong> For scripts and CI, use <code>DATE=</code>, <code>REFRESH=</code>, <code>YES=1</code>, <code>FORCE=1</code> as needed. Use <code>VERBOSE=1</code> for run IDs on log lines. Use <code>FAIL_FAST=1</code> for fail-fast batch runs, and <code>ARGS=&quot;...&quot;</code> to pass extra CLI flags.</p><h2 id="make-variables-→-cli-flags" tabindex="-1">Make variables → CLI flags <a class="header-anchor" href="#make-variables-→-cli-flags" aria-label="Permalink to &quot;Make variables → CLI flags&quot;">​</a></h2><p>The Makefile is the source of truth. All commands are invoked via <code>make &lt;target&gt;</code>; the CLI receives variables as flags.</p><table tabindex="0"><thead><tr><th>Make variable</th><th>CLI flag / behaviour</th><th>Example</th></tr></thead><tbody><tr><td><code>BRAND</code></td><td>First positional arg after command</td><td><code>make build</code> → <code>node … refresh loft</code></td></tr><tr><td><code>DATE</code></td><td><code>--date=YYYY-MM-DD</code></td><td><code>make build DATE=2026-02-14</code></td></tr><tr><td><code>REFRESH</code></td><td><code>--refresh=r1</code></td><td><code>make push REFRESH=r2</code></td></tr><tr><td><code>FORCE=1</code></td><td><code>--force</code></td><td><code>make build FORCE=1</code></td></tr><tr><td><code>YES=1</code></td><td><code>--yes</code> (skip confirmation/approval prompts)</td><td><code>make push-all YES=1</code></td></tr><tr><td><code>ALL=1</code></td><td><code>build</code>/<code>push</code>: <code>--all-refreshes</code> (all refreshes in a date); <code>status</code>: <code>--show-all</code> (full history)</td><td><code>make status ALL=1</code></td></tr><tr><td><code>FAIL_FAST=1</code></td><td>Stop <code>build-all</code>/<code>push-all</code> on first failure (default: continue)</td><td><code>make build-all FAIL_FAST=1</code></td></tr><tr><td><code>ARGS=&quot;...&quot;</code></td><td>Pass extra CLI flags (appended after mapped vars)</td><td><code>make push ARGS=&quot;--yes --force&quot;</code></td></tr><tr><td><code>SKIP_FETCH=1</code></td><td><code>--skip-fetch</code></td><td><code>make pull SKIP_FETCH=1</code></td></tr><tr><td><code>CONVERT=1</code></td><td><code>--convert</code></td><td><code>make pull CONVERT=1</code></td></tr><tr><td><code>PULL=1</code></td><td>status: <code>--pull</code> (bypass throttles)</td><td><code>make status PULL=1</code></td></tr><tr><td><code>VERBOSE=1</code></td><td><code>--verbose</code></td><td><code>make push VERBOSE=1</code></td></tr><tr><td><code>COPY=1</code></td><td><code>--copy</code></td><td><code>make email COPY=1</code></td></tr><tr><td><code>TO</code></td><td>(switch brand — via <code>make setup</code>)</td><td><code>make setup</code></td></tr><tr><td><code>SOURCE</code></td><td>(switch data source — via <code>make setup</code>)</td><td><code>make setup</code></td></tr><tr><td><code>OP</code></td><td>(reports operation)</td><td><code>make reports OP=stats</code> (default: dates)</td></tr></tbody></table><p><strong>Source &amp; OCAPI:</strong> Use <code>make setup</code> to switch data source (local/Smartsheet) and enable/disable SFCC sync. The setup wizard handles brand, source, and OCAPI configuration.</p><h2 id="per-command-pages" tabindex="-1">Per-command pages <a class="header-anchor" href="#per-command-pages" aria-label="Permalink to &quot;Per-command pages&quot;">​</a></h2><ul><li><strong>Producer:</strong> <a href="/ocapi-docs.github.io/cli/status.html">status</a> · <a href="/ocapi-docs.github.io/cli/pull.html">pull</a> · <a href="/ocapi-docs.github.io/cli/preview.html">preview</a> · <a href="/ocapi-docs.github.io/cli/push.html">push</a> · <a href="/ocapi-docs.github.io/cli/commit.html">commit</a> · <a href="/ocapi-docs.github.io/cli/build.html">build</a> · <a href="/ocapi-docs.github.io/cli/browse.html">browse</a> · <a href="/ocapi-docs.github.io/cli/replicate.html">replicate</a> · <a href="/ocapi-docs.github.io/cli/email.html">email</a> · <a href="/ocapi-docs.github.io/cli/refresh.html">refresh</a></li><li><strong>Dev &amp; Ops:</strong> <a href="/ocapi-docs.github.io/cli/setup.html">setup</a> · <a href="/ocapi-docs.github.io/cli/upload.html">upload</a> · <a href="/ocapi-docs.github.io/cli/delete.html">delete</a> · <a href="/ocapi-docs.github.io/cli/registry.html">registry</a> · <a href="/ocapi-docs.github.io/cli/health.html">health</a> · <a href="/ocapi-docs.github.io/cli/excel.html">excel</a> · <a href="/ocapi-docs.github.io/cli/reports.html">reports</a> · <a href="/ocapi-docs.github.io/cli/validate.html">validate</a> · <a href="/ocapi-docs.github.io/cli/sync.html">sync</a></li></ul><p>For full workflow and example output, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a>. For a walkthrough of blocking errors and approval steps, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a>.</p>',15)])])}const p=e(r,[["render",c]]);export{h as __pageData,p as default};
